<script setup>
import { ref, computed, shallowRef, watch, onBeforeUnmount } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import LifeTreeDom from '../components/LifeTreeDom.vue';
import { Archive, importProject, listProjects, loadProject, Model } from '../ls/projects.js';
import { toDomDocument, layoutDocument, exportSvg } from '../ls/renderer.js';
import { apiRequest } from '../services/api.js';
import { useUserStore } from '../stores/user.js';
const route=useRoute(),router=useRouter(),user=useUserStore();
const projects=ref([]),current=shallowRef(null),loaded=shallowRef(new Map()),collapsed=ref(new Set()),selection=ref(null),status=ref(''),busy=ref(false),paper=ref(false),treeIndex=ref(0),checkout=ref(null),leaseTimer=ref(null),importInput=ref(null),returnInput=ref(null);
const modelDoc=computed(()=>{if(!current.value)return null;return toDomDocument(current.value,{loaded:loaded.value,treeIndex:treeIndex.value});});
const layout=computed(()=>{if(!modelDoc.value)return null;try{return layoutDocument(modelDoc.value,{collapsed:collapsed.value,timeScale:paper.value});}catch(e){return {...layoutDocument(modelDoc.value,{collapsed:collapsed.value}),timeError:e.message};}});
const selected=computed(()=>modelDoc.value?.nodeMap.get(selection.value));
const axis=computed(()=>layout.value?.axis),geo=computed(()=>current.value?.model.views?.geologicalTime);
async function task(fn){if(busy.value)return;busy.value=true;try{await fn();}catch(e){status.value=e.message;}finally{busy.value=false;}}
async function refresh(){projects.value=await listProjects();}
async function open(id){await task(async()=>{status.value='';let p;try{p=await loadProject(id);}catch{const response=await apiRequest('/api/ls/projects/'+encodeURIComponent(id));p={manifest:{uid:response.uid,title:response.title,updatedAt:response.revision},model:response.model};}current.value=p;loaded.value=new Map();collapsed.value=new Set();selection.value=null;treeIndex.value=0;const doc=toDomDocument(p);for(const key of doc.moduleMap.keys())collapsed.value.add(key);});}
watch(()=>route.params.id,id=>{if(id)open(String(id));},{immediate:true});
async function importFiles(event){await task(async()=>{for(const file of event.target.files||[]){const record=await importProject(file);status.value='已导入 '+record.title;}await refresh();});event.target.value='';}
async function chooseMain(){if(!current.value)return;await task(async()=>{const p=current.value;if(p.zip){await apiRequest('/api/ls/projects',{method:'POST',body:{uid:p.manifest.uid,title:p.manifest.title,model:p.model}});}await apiRequest('/api/ls/main',{method:'PUT',body:{projectUid:p.manifest.uid}});status.value='已指定网站 LS 主树';});}
async function publish(){if(!current.value)return;await task(async()=>{const p=current.value;await apiRequest('/api/ls/projects',{method:'POST',body:{uid:p.manifest.uid,title:p.manifest.title,model:p.model}});status.value='工程模型已上传；引用的子工程也需要分别上传。';});}
async function toggle(id){const ref=modelDoc.value.moduleMap.get(id);if(ref&&!loaded.value.has(id)){await task(async()=>{let p;try{p=await loadProject(ref.moduleUid);}catch{const response=await apiRequest('/api/ls/projects/'+encodeURIComponent(ref.moduleUid));p={manifest:{uid:response.uid,title:response.title,updatedAt:response.revision},model:response.model};}if(ref.path.includes(p.manifest.uid))throw Error('工程循环引用，无法展开');const map=new Map(loaded.value);map.set(id,p);loaded.value=map;const next=new Set(collapsed.value);next.delete(id);collapsed.value=next;});return;}const next=new Set(collapsed.value);if(next.has(id))next.delete(id);else next.add(id);collapsed.value=next;}
function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function svg(){if(!layout.value||layout.value.timeError){status.value=layout.value?.timeError||'请先打开工程';return;}download(current.value.manifest.title+'.svg',exportSvg(modelDoc.value,layout.value),'image/svg+xml');}
async function beginEdit(){if(!selected.value)return;await task(async()=>{const s=selected.value;checkout.value=await apiRequest('/api/ls/checkout',{method:'POST',body:{projectUid:s.projectUid,rootUid:s.nodeUid}});const raw=checkout.value;const base=await Archive.create(await minimalXmind(raw.model),'子树修改');base.model=raw.model;base.editor.sheets=Model.toXmind(raw.model);base.manifest.checkout={projectUid:s.projectUid,rootUid:s.nodeUid,token:raw.token,revision:raw.revision,expiresAt:raw.expiresAt};const bytes=await Archive.build(base,base.editor.sheets,{type:'uint8array'});download('修改-'+Model.label(s.node)+'.ls',bytes,'application/octet-stream');status.value='已签出所选节点及其后代；重叠子树已锁定。请在 APK 修改后导回提交。';startHeartbeat();});}
async function minimalXmind(model){const {default:JSZip}=await import('jszip');const z=new JSZip();z.file('content.json',JSON.stringify(Model.toXmind(model)));z.file('metadata.json',JSON.stringify({dataStructureVersion:'2',layoutEngineVersion:'3'}));z.file('manifest.json','{"file-entries":{}}');return z.generateAsync({type:'uint8array'});}
function startHeartbeat(){clearInterval(leaseTimer.value);leaseTimer.value=setInterval(async()=>{if(!checkout.value)return;try{await apiRequest('/api/ls/checkout',{method:'PATCH',body:{token:checkout.value.token}});}catch(e){clearInterval(leaseTimer.value);status.value='编辑锁未能续期：'+e.message;}},120000);}
async function release(){if(!checkout.value)return;await task(async()=>{await apiRequest('/api/ls/checkout',{method:'DELETE',body:{token:checkout.value.token}});checkout.value=null;clearInterval(leaseTimer.value);status.value='已释放编辑锁';});}
async function submit(event){await task(async()=>{const file=event.target.files[0];if(!file)return;const p=await Archive.load(await file.arrayBuffer()),c=p.manifest.checkout;if(!c)throw Error('这个工程没有网站签出记录');await apiRequest('/api/ls/commit',{method:'POST',body:{...c,model:p.model}});checkout.value=null;clearInterval(leaseTimer.value);status.value='子树修改已提交；其他分支保持原样。';});event.target.value='';}
onBeforeUnmount(()=>clearInterval(leaseTimer.value));
refresh().catch(e=>status.value=e.message);
if(!route.params.id)apiRequest('/api/ls/main').then(result=>{if(result.projectUid)router.replace('/ls/'+encodeURIComponent(result.projectUid));}).catch(()=>{});
</script>
<template><div class="ls-workspace"><header><RouterLink to="/life-tree">生命树</RouterLink><h1>LS 工程</h1><button @click="importInput.click()" :disabled="busy">导入 LS 工程</button><input ref="importInput" type="file" multiple accept=".ls,.lsproj" hidden @change="importFiles"><select v-if="projects.length" @change="router.push('/ls/'+$event.target.value)"><option value="">选择本机工程</option><option v-for="p in projects" :key="p.uid" :value="p.uid">{{p.title}}</option></select><button v-if="current&&user.isLoggedIn" @click="publish">上传模型</button><button v-if="current&&user.isSiteOwner" @click="chooseMain">指定为主树</button></header><p v-if="status" class="status" role="status">{{status}}</p><template v-if="current"><nav><strong>{{current.manifest.title}}</strong><select v-if="current.model.trees.length>1" v-model="treeIndex"><option v-for="(t,i) in current.model.trees" :key="t.uid" :value="i">{{t.title}}</option></select><label><input type="checkbox" v-model="paper">按时间比例</label><button @click="svg">导出 SVG</button><button :disabled="!selected||busy" @click="beginEdit">编辑此节点及后代</button><button @click="returnInput.click()">提交修改后的 LS</button><input ref="returnInput" type="file" accept=".ls" hidden @change="submit"><button v-if="checkout" @click="release">释放编辑锁</button></nav><p v-if="layout.timeError" class="status">{{layout.timeError}} 当前显示拓扑示意图。</p><div class="reader"><section class="canvas"><div v-if="axis&&(!geo||geo.positions.includes('top'))" class="time-axis" :style="{width:layout.width+'px'}"><span v-for="i in 6" :key="i" :style="{left:(axis.left+(i-1)*(axis.right-axis.left)/5)+'px'}">{{(axis.from-(i-1)*(axis.from-axis.to)/5).toFixed(1)}} Ma</span></div><LifeTreeDom :document="modelDoc" :layout-override="layout" :collapsed-ids="collapsed" :highlight-node-id="selection||''" selectable @node-select="selection=$event" @toggle-collapse="toggle"/><div v-if="axis&&geo?.positions.includes('bottom')" class="time-axis" :style="{width:layout.width+'px'}"><span v-for="i in 6" :key="i" :style="{left:(axis.left+(i-1)*(axis.right-axis.left)/5)+'px'}">{{(axis.from-(i-1)*(axis.from-axis.to)/5).toFixed(1)}} Ma</span></div><ol v-if="modelDoc.citations.length" class="references"><li v-for="(r,i) in modelDoc.citations" :key="i">{{r.title}} {{r.authors}} {{r.year}} {{r.doi}}</li></ol></section><aside v-if="selected"><h2>{{Model.label(selected.node)}}</h2><dl><template v-for="(value,key) in selected.node" :key="key"><dt v-if="value!==null&&key!=='uid'">{{key}}</dt><dd v-if="value!==null&&key!=='uid'">{{Array.isArray(value)?value.map(x=>typeof x==='object'?JSON.stringify(x):x).join('；'):typeof value==='object'?JSON.stringify(value):value}}</dd></template></dl></aside></div></template><div v-else class="empty"><h2>打开 LS 工程，沿用现有 DOM 生命树阅读器</h2><p>子工程在展开时加载并缓存。可将一个已上传工程指定为网站主树。</p></div></div></template>
<style scoped>.ls-workspace{min-height:100vh;background:white;color:#20252a;font:14px system-ui,sans-serif}header,nav{display:flex;align-items:center;gap:12px;padding:14px 22px;border-bottom:1px solid #ddd;flex-wrap:wrap}h1{font-size:20px;margin:0 auto 0 0}button,select{border:1px solid #d5d9dd;background:white;border-radius:5px;padding:8px 12px;color:#283640}button:disabled{opacity:.45}.status{padding:12px 22px;background:#fff6df;margin:0}.reader{display:flex;align-items:flex-start}.canvas{overflow:auto;flex:1;min-width:0;max-height:82vh}.time-axis{position:relative;height:45px;border-bottom:1px solid #777}.time-axis span{position:absolute;top:15px;font-size:11px;transform:translateX(-50%)}aside{width:300px;flex:none;border-left:1px solid #ddd;padding:20px;max-height:82vh;overflow:auto}aside h2{font-size:17px}dt{font-size:12px;color:#657079;margin-top:10px}dd{margin:3px 0;overflow-wrap:anywhere}.references{font-size:12px;line-height:1.8;padding:20px 45px}.empty{padding:70px 30px;text-align:center;color:#657079}@media(max-width:800px){aside{position:fixed;bottom:0;left:0;right:0;width:auto;max-height:30vh;background:white;border-top:1px solid #ddd}.canvas{padding-bottom:30vh}}</style>
